  71: "Light snow", 73: "Moderate snow", 75: "Heavy snow",
  80: "Light showers", 81: "Moderate showers", 82: "Violent showers",
  95: "Thunderstorm"
};
const condition = codeMap[weatherCode] || "Unknown conditions";
const summary = `Bellevue weather: ${tempF}F, ${condition}`;
return { summary, temperatureF: tempF, condition };"
